window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["ansible-64-br-ansible"]={"html":"\r\n\r\n\r\n\r\n▶ الدليل الشامل لتعلم Ansible — By Nabawy — REDLINE Daylight v6\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"sheet cover\">\r\n  <div class=\"stamp\">▶_</div>\r\n  <div class=\"ckick\">REDLINE DAYLIGHT · AUTOMATION HANDBOOK</div>\r\n  <h1 id=\"الدليل-الشامللتعلُّم-ansible\">الدليل الشامل<br />لتعلُّم Ansible</h1>\r\n  <div class=\"ambrule\"></div>\r\n  <div class=\"sub\">مرجعك الكامل لـ <b>Ansible</b> — الـ Architecture، التثبيت على كل الأنظمة، إعداد الـ SSH Keys، الـ Modules والـ Inventory، الـ Ad-hoc Commands، أساسيات الـ YAML، الـ Playbooks بالكامل مع قراءة النتائج، والـ Roles مع منصة Galaxy — بناءً على شرح قناة <b>Cloud Code</b>، تفريغًا وتصحيحًا وتنظيمًا كمرجع مكتوب متكامل. كل المصطلحات التقنية بالإنجليزية كما هي في بيئة العمل.</div>\r\n  <div class=\"byline\">By Nabawy<small>AUTHOR &amp; COMPILER · إعداد وتنسيق</small></div>\r\n  <div class=\"vols\">\r\n    <div class=\"volcard on\">REDLINE EDITION<small>نسخة نهارية · A4-Fixed</small></div>\r\n    <div class=\"volcard\">SSH<small>اتصال آمن</small></div>\r\n    <div class=\"volcard\">YAML<small>لغة الـ Playbooks</small></div>\r\n    <div class=\"volcard\">Roles<small>تنظيم احترافي</small></div>\r\n  </div>\r\n  <div class=\"cver\">AGENTLESS · DECLARATIVE · IDEMPOTENT — V6 · BY NABAWY</div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Contents</div><h1 id=\"المحتويات\">📖 المحتويات</h1></div><span class=\"hmeta\">12 فصلًا + ملحقات</span></div></div>\r\n  <div class=\"tocgrid\">\r\n    <div>\r\n      <a href=\"#summary\"><span class=\"tnum\">🗺️</span><span>الخريطة — ملخص تنفيذي</span><span class=\"dots\"></span><span class=\"tp\">3</span></a>\r\n      <a href=\"#ch-01\"><span class=\"tnum\">01</span><span>Intro — مقدمة ومميزات Ansible</span><span class=\"dots\"></span><span class=\"tp\">4</span></a>\r\n      <a href=\"#ch-02\"><span class=\"tnum\">02</span><span>Architecture — المعمارية</span><span class=\"dots\"></span><span class=\"tp\">5</span></a>\r\n      <a href=\"#ch-03\"><span class=\"tnum\">03</span><span>Comparison — مقارنة طرق الإدارة</span><span class=\"dots\"></span><span class=\"tp\">6</span></a>\r\n      <a href=\"#ch-04\"><span class=\"tnum\">04</span><span>Use Cases — مجالات الاستخدام</span><span class=\"dots\"></span><span class=\"tp\">7</span></a>\r\n      <a href=\"#ch-05\"><span class=\"tnum\">05</span><span>Installation — التثبيت وإعداد البيئة</span><span class=\"dots\"></span><span class=\"tp\">8</span></a>\r\n      <a href=\"#ch-06\"><span class=\"tnum\">06</span><span>SSH Keys — الاتصال بدون Password</span><span class=\"dots\"></span><span class=\"tp\">9</span></a>\r\n      <a href=\"#ch-07\"><span class=\"tnum\">07</span><span>Modules — وحدات التنفيذ</span><span class=\"dots\"></span><span class=\"tp\">10</span></a>\r\n    </div>\r\n    <div>\r\n      <a href=\"#ch-08\"><span class=\"tnum\">08</span><span>Inventory — ملف الـ Servers</span><span class=\"dots\"></span><span class=\"tp\">11</span></a>\r\n      <a href=\"#ch-09\"><span class=\"tnum\">09</span><span>Ad-hoc Commands — التنفيذ الفوري</span><span class=\"dots\"></span><span class=\"tp\">12</span></a>\r\n      <a href=\"#ch-10\"><span class=\"tnum\">10</span><span>YAML Basics — أساسيات الصيغة</span><span class=\"dots\"></span><span class=\"tp\">13</span></a>\r\n      <a href=\"#ch-11\"><span class=\"tnum\">11</span><span>Playbooks — كتابة وتشغيل</span><span class=\"dots\"></span><span class=\"tp\">14</span></a>\r\n      <a href=\"#ch-11b\"><span class=\"tnum\">11·b</span><span>Playbooks — الإزالة وقراءة النتائج</span><span class=\"dots\"></span><span class=\"tp\">15</span></a>\r\n      <a href=\"#ch-12\"><span class=\"tnum\">12</span><span>Roles &amp; Galaxy — التنظيم</span><span class=\"dots\"></span><span class=\"tp\">16</span></a>\r\n      <a href=\"#quiz\"><span class=\"tnum\">🎯</span><span>اختبر نفسك — 12 سؤالًا</span><span class=\"dots\"></span><span class=\"tp\">17</span></a>\r\n      <a href=\"#answers\"><span class=\"tnum\">✅</span><span>مفتاح الإجابات</span><span class=\"dots\"></span><span class=\"tp\">18</span></a>\r\n      <a href=\"#cheatsheet\"><span class=\"tnum\">📌</span><span>الورقة المرجعية</span><span class=\"dots\"></span><span class=\"tp\">19</span></a>\r\n    </div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [دليل ألوان الحالة]<span class=\"hst\">status legend</span></div>\r\n  <div class=\"lgd\">\r\n    <div><span class=\"dot8\"></span><span class=\"stbad st-ok\">ok</span> — الـ Server بالحالة المطلوبة، لا تغيير</div>\r\n    <div><span class=\"dot8\"></span><span class=\"stbad st-chg\">changed</span> — تم تنفيذ تغيير بنجاح</div>\r\n    <div><span class=\"dot8\"></span><span class=\"stbad st-fail\">failed</span> — حدث خطأ في الـ Task</div>\r\n    <div><span class=\"dot8\"></span> RED — عناوين وهيكل (ديكور بنيوي)</div>\r\n  </div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG</span><b>كيف تستخدم الكتاب:</b> 12 فصلًا مترابطًا — كل فصل يفتح بما قبله ويجهّزك لما بعده. كل المصطلحات التقنية بالإنجليزية كما في بيئة العمل (Agentless, Playbook, Inventory…) والشرح بالعربية. الأكواد تُقرأ من اليسار والنص من اليمين. أي سطر مفقود من ملفك الأصلي موجود هنا — قارن بحرية.</div>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 2 —</span><span><a href=\"#toc\">▤ TOC</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Executive Summary</div><h1 id=\"الملخص-التنفيذي-الطريق-كاملًا\">🗺️ الملخص التنفيذي — الطريق كاملًا</h1></div><span class=\"hmeta\">ابدأ من هنا</span></div></div>\r\n  <p>قبل أن نلمس أي سطر أوامر، هذه هي القصة كاملة — كل جملة رابط يأخذك لفصلها مباشرة.</p>\r\n  <p>نبدأ بسؤال وجودي: <b>لماذا نُتعب أنفسنا بالدخول لكل Server يدويًا؟</b> الإجابة تبدأ في <a href=\"#ch-01\">الفصل 1 — Intro</a>: Ansible أداة <b>Automation</b> مفتوحة المصدر (<b>Open-Source</b>)، بدون عملاء <b>Agentless</b>، بصيغة <b>YAML</b> بسيطة، بأسلوب <b>Declarative</b>، وآمنة على التكرار <b>Idempotent</b>. ثم نرى في <a href=\"#ch-02\">الفصل 2 — Architecture</a> الصورة ببُعديها: <b>Control Node</b> يهمس عبر <b>SSH Connection</b> بزوج <b>Public/Private Keys</b> إلى <b>Managed Nodes</b> (Ubuntu / CentOS / DB).</p>\r\n  <p>ثم في <a href=\"#ch-03\">الفصل 3 — Comparison</a> نضع Ansible في الميزان ضد الطريقة الـ Manual وسكربتات الـ Bash على 3 Servers مختلفة التوزيعات (Ubuntu، CentOS، Alpine) لتثبيت Nginx. وفي <a href=\"#ch-04\">الفصل 4 — Use Cases</a> نستعرض المجالات الثلاثة: <b>Configuration Management</b>، <b>Infrastructure Provisioning</b> (ومن هنا نتحدث عن Terraform)، و<b>Network Automation</b>.</p>\r\n  <p>الآن العدة العملية: في <a href=\"#ch-05\">الفصل 5 — Installation</a> نثبّت على macOS وUbuntu وPip وWSL، ونجهّز الـ VS Code Extensions. وفي <a href=\"#ch-06\">الفصل 6 — SSH Keys</a> ننشئ الـ Key Pair بـ <code>ssh-keygen</code> ونرفع الـ Public Key بـ <code>ssh-copy-id</code> — الأساس الذي تقف عليه كل أتمتة قادمة.</p>\r\n  <p>اللغة والتنفيذ: في <a href=\"#ch-07\">الفصل 7 — Modules</a> نتعرّف apt/yum وping وservice وcopy وcommand/shell. وفي <a href=\"#ch-08\">الفصل 8 — Inventory</a> نكتب ملف hosts.ini بالمجموعات. ثم في <a href=\"#ch-09\">الفصل 9 — Ad-hoc Commands</a> نفحص وننفّذ فورًا. وفي <a href=\"#ch-10\">الفصل 10 — YAML</a> نتقن الـ Indentation وهياكل البيانات.</p>\r\n  <p>الذروة: في <a href=\"#ch-11\">الفصل 11 — Playbooks</a> نكتب Playbook تثبيت وتشغيل Apache كاملًا ونشغّله ونقرأ الـ Recap، وفي <a href=\"#ch-11b\">الفصل 11·b</a> نعكسه بالإزالة. وأخيرًا في <a href=\"#ch-12\">الفصل 12 — Roles &amp; Galaxy</a> ننظم ونشارك. اختم بـ <a href=\"#quiz\">الاختبار</a> و<a href=\"#cheatsheet\">المرجع السريع</a>. الطريق واضح. ▶</p>\r\n  <div class=\"m-key\"><span class=\"tag\">KEY IDEA</span><b>الفكرة الجامعة:</b> أنت تكتب الـ Desired State مرة واحدة، وAnsible يحققها على كل الـ Managed Nodes — وإن لم تكن بحاجة فعلية للتغيير، فلن يلمس شيئًا.</div>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 3 —</span><span><a href=\"#toc\">▤ TOC</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 01</div><h1 id=\"intro-مقدمة-ونظرة-عامة\">🤖 Intro <span class=\"har\">— مقدمة ونظرة عامة</span></h1></div><span class=\"hmeta\">🟢 6 MIN</span></div></div>\r\n  <p><b>Ansible</b> هي أداة <b>Automation</b> مفتوحة المصدر (<b>Open-Source</b>) تُستخدم بشكل أساسي في مجالين:</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>1️⃣ Configuration Management</p><p>إدارة الإعدادات — تثبيت وتحديث البرامج وضبط الملفات على الـ Servers.</p></div>\r\n    <div class=\"panel\"><p>2️⃣ Infrastructure Provisioning</p><p>بناء وتجهيز البنية التحتية — إنشاء الـ Servers والموارد السحابية.</p></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [أهم مميزات Ansible الأساسية]<span class=\"hst\">the four pillars</span></div>\r\n  <h3 id=\"1-1agentless-بدون-عميل\"><span class=\"n\">1.1</span>Agentless — بدون عميل</h3>\r\n  <ul>\r\n    <li>📦 لا تحتاج لتثبيت أي برامج أو <b>Agents</b> على الـ <b>Managed Nodes</b> المستهدفة.</li>\r\n    <li>🔌 الاتصال يتم عبر بروتوكول <b>SSH</b> (في أنظمة Linux) أو <b>WinRM/SSH</b> (في أنظمة Windows).</li>\r\n    <li>🐍 المتطلب الوحيد على Servers الـ Linux هو وجود بيئة <b>Python</b>.</li>\r\n  </ul>\r\n  <h3 id=\"1-2simple-syntax-صيغة-بسيطة\"><span class=\"n\">1.2</span>Simple Syntax — صيغة بسيطة</h3>\r\n  <p>تُكتب جميع الإعدادات وسيناريوهات التشغيل بلغة <b>YAML</b> — وهي لغة قراءة وكتابة بسيطة جدًا وسهلة التعلم والتنفيذ. لا أقواس معقدة ولا فاصيل منقوطة؛ فقط مسافات وترتيب.</p>\r\n  <h3 id=\"1-3declarative-approach-الأسلوب-التوصيفي\"><span class=\"n\">1.3</span>Declarative Approach — الأسلوب التوصيفي</h3>\r\n  <p>تحدد في ملف الـ YAML الـ <b>Desired State</b> (الحالة المطلوبة) — مثل: «أريد تثبيت Apache وGit» — ويقوم Ansible بتنفيذ الـ Steps اللازمة للوصول لهذه الحالة بنفسه. ويدعم أيضًا الـ <b>Imperative Approach</b> عند استخدام الـ <b>Ad-hoc Commands</b>.</p>\r\n  <h3 id=\"1-4idempotency-التكرار-الآمن\"><span class=\"n\">1.4</span>Idempotency — التكرار الآمن ♻️</h3>\r\n  <p>تعني أن تنفيذ نفس الـ Script عدة مرات متتالية <b>لن يغيّر شيئًا إلا إذا كانت هناك حاجة فعلية للتغيير</b>.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">EXAMPLE</span>إذا طلبت من Ansible تثبيت Apache وكان البرنامج مثبتًا بالفعل بنفس الإصدار → لن يعيد تثبيته ولن يحدث أي تغيير على الـ Server. ستظهر الحالة <span class=\"stbad st-ok\">ok</span>. غير مثبت؟ يثبته → <span class=\"stbad st-chg\">changed</span>.</div>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">Agentless</span><span class=\"chipr\">Simple YAML</span><span class=\"chipr\">Declarative</span><span class=\"chipr\">Idempotent</span>\r\n  </div>\r\n  <p>⏭️ كيف تُبنى هذه الأداة داخليًا؟ مكوّنان فقط — <a href=\"#ch-02\">الفصل 2: Architecture</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 4 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-02\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 02</div><h1 id=\"architecture-معمارية-ansible\">🏗️ Architecture <span class=\"har\">— معمارية Ansible</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n  <p>تتكون معمارية Ansible من <b>مكوّنين رئيسيين</b> — بساطة متعمدة هي سر قوتها.</p>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">Architecture — المكوّنان والقناة بينهما</div>\r\n    <div class=\"frow\">\r\n      <div class=\"blk b-red\">Control Node<small>Laptop / Linux Server — عليه Ansible</small></div>\r\n      <span class=\"harrow\">━━━ SSH Connection ──►</span>\r\n      <div class=\"blk\">Managed Node<small>Ubuntu / CentOS / DB</small></div>\r\n    </div>\r\n    <p>القناة: <b>Public/Private Key Pair</b> — الاتصال مؤمَّن بلا Passwords.</p>\r\n  </div>\r\n  <h3 id=\"2-1control-node-عقدة-التحكم\"><span class=\"n\">2.1</span>Control Node — عقدة التحكم</h3>\r\n  <p>الجهاز أو الـ Server الذي يتم تثبيت <b>Ansible</b> عليه، ومن خلاله يقوم مهندس الـ <b>DevOps</b> بتشغيل الأوامر وكتيبات التشغيل (<b>Playbooks</b>). يمكن أن يكون Laptop شخصيًا أو Linux Server في معمل أو Cloud.</p>\r\n  <h3 id=\"2-2managed-nodes-targets-العقد-المُدارة\"><span class=\"n\">2.2</span>Managed Nodes (Targets) — العقد المُدارة</h3>\r\n  <p>الـ Servers المستهدفة بتطبيق التغييرات والإعدادات. تتلقى الـ Instructions عبر <b>SSH</b> وتنفذها <b>بدون الحاجة لتثبيت Agents عليها</b> — لهذا نسمي المعمارية Agentless.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>لاحظ ما لا يوجد: لا Database مركزية، لا Daemon يعمل باستمرار على الـ Targets، لا Agent يُحدَّث. Ansible يتصل عند الحاجة، ينفّذ، ثم يرحل. العبء على الـ Managed Nodes = صفر.</div>\r\n  <div class=\"taskhead\">TASK [خريطة المكونات]<span class=\"hst\">component map</span></div>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>المكوّن</th><th>ما هو؟</th><th>ماذا يُثبَّت عليه؟</th><th>دوره</th></tr>\r\n    <tr><td><b>Control Node</b></td><td>Laptop / Linux Server</td><td><b>Ansible</b> (وحده)</td><td>تشغيل الأوامر والـ Playbooks</td></tr>\r\n    <tr><td><b>Managed Nodes</b></td><td>Ubuntu / CentOS / DB…</td><td>لا شيء — Python فقط</td><td>استقبال أوامر SSH وتنفيذها</td></tr>\r\n  </table></div></div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>خطأ شائع عند المبتدئين: محاولة تثبيت Ansible على الـ Managed Nodes «احتياطًا». لا تفعل — هي لا تحتاجه إطلاقًا. الـ Control Node هو المكان الوحيد للتثبيت (سنعود له في فصل الـ Installation).</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>سؤال المقابلة: «صِف معمارية Ansible؟» → <b>مكوّنان</b>: Control Node (عليه Ansible، منه التشغيل) + Managed Nodes (تستقبل عبر SSH بلا Agents)، والقناة بينهما Key Pair. بساطة معمارية = سهولة تشغيل.</div>\r\n  <p>⏭️ المعمارية صافية — لكن كيف تتفوق على الطرق التقليدية؟ مقارنة عملية على 3 Servers → <a href=\"#ch-03\">الفصل 3: Comparison</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 5 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-01\">السابق</a> · <a href=\"#ch-03\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 03</div><h1 id=\"comparison-مقارنة-طرق-إدارة-الـ-servers\">⚖️ Comparison <span class=\"har\">— مقارنة طرق إدارة الـ Servers</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n  <p>تخيل أنك مهندس تدير <b>3 سيرفرات Linux</b> مختلفة التوزيعات — <b>Ubuntu، CentOS، Alpine</b> — وتريد تثبيت <b>Nginx</b> عليها. ثلاث طرق أمامك، والفارق بينها فلسفة كاملة:</p>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>وجه المقارنة</th><th>🖐️ Manual</th><th>📜 Bash Scripts</th><th>▶️ Ansible</th></tr>\r\n    <tr><td><b>آلية العمل</b></td><td>الدخول عبر SSH لكل Server وتنفيذ الأوامر يدويًا.</td><td>كتابة Script Bash يتعرف على الـ OS وينفذ الأوامر.</td><td>كتابة ملف YAML بسيط يُعرّف الـ Desired State للجميع.</td></tr>\r\n    <tr><td><b>السرعة والجهد</b></td><td>بطيئة وتكثر فيها الأخطاء.</td><td>تتطلب خبرة عالية في الـ Scripting.</td><td>سريعة، مركزية، وSimple Syntax.</td></tr>\r\n    <tr><td><b>Idempotency</b></td><td>غير متوفرة — تدخل يدوي للتأكد.</td><td>غير متوفرة تلقائيًا — شروط تُكتب يدويًا.</td><td><b>مدعومة تلقائيًا ✓</b></td></tr>\r\n    <tr><td><b>دعم التوزيعات</b></td><td>تتطلب معرفة أوامر كل توزيعة (<code>apt</code>, <code>yum</code>, <code>apk</code>).</td><td>تتطلب كتابة <code>if/else</code> لكل OS.</td><td><b>الـ Modules تتكفل تلقائيًا ✓</b></td></tr>\r\n  </table></div></div>\r\n  <div class=\"mark m-fun\"><span class=\"tag\">ASIDE · المفارقة</span>لاحظ أن Bash Scripts أذكى من Manual لكنها تتراكم: كل توزيعة جديدة = فرع <code>if/else</code> جديد، وكل تحديث = مراجعة كل السكربتات. Ansible يقلب المعادلة: أنت لا تكتب <b>كيف</b> التنفيذ — أنت تكتب <b>ماذا</b> تريد، وهو يعرف الـ How لكل توزيعة داخل الـ Modules.</div>\r\n  <div class=\"taskhead\">TASK [قراءة الجدول عمليًا]<span class=\"hst\">reading the table</span></div>\r\n  <p>بمعايير حقيقية: لتثبيت Nginx يدويًا على الثلاثة ستحتاج 3 جلسات SSH و3 أوامر مختلفة (<code>apt install</code> / <code>yum install</code> / <code>apk add</code>) وتحققًا يدويًا من كل واحد. بـ Bash: Script واحد لكن بشروط تشعبية لكل Package Manager. بـ Ansible: <b>Task واحدة</b> — <code>package: name=nginx state=present</code> — تعمل على الثلاثة، وتتحقق الـ Idempotency تلقائيًا في كل Run قادم.</p>\r\n  <div class=\"mark m-exam\"><span class=\"tag\">🎓 EXAM</span>احفظ أزواج المقارنة: Manual = بطء + أخطاء + لا Idempotency · Bash = مركزي لكن Scripting ثقيل + شروط يدوية · Ansible = <b>YAML مركزي + Idempotency تلقائية + Modules تتكفل بالتوزيعات</b>. هذه المقارنة نفسها سؤال مقابلة متكرر.</div>\r\n  <p>⏭️ اقتنعنا بالتفوق — أين تُستخدم فعلًا؟ المجالات الثلاثة الكبرى → <a href=\"#ch-04\">الفصل 4: Use Cases</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 6 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-02\">السابق</a> · <a href=\"#ch-04\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 04</div><h1 id=\"use-cases-مجالات-الاستخدام-الرئيسية\">🌍 Use Cases <span class=\"har\">— مجالات الاستخدام الرئيسية</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n  <p>ثلاثة ميادين رئيسية تشغل فيها Ansible اليوم — الأول هو الأشهر والأهم، والثاني يحمل نقاشًا معروفًا في المجال.</p>\r\n  <h3 id=\"4-1configuration-management-إدارة-الإعدادات\"><span class=\"n\">4.1</span>Configuration Management — إدارة الإعدادات</h3>\r\n  <p><b>الاستخدام الأشهر والأهم:</b> تثبيت وتحديث الـ <b>Packages</b>، ضبط الـ <b>Files</b>، وتحديث الـ Servers من مكان واحد — سواء كانت الـ Servers في Datacenter محلي أو على الـ Cloud. مئات الـ Servers، Command واحدة.</p>\r\n  <h3 id=\"4-2infrastructure-provisioning-بناء-البنية-التحتية\"><span class=\"n\">4.2</span>Infrastructure Provisioning — بناء البنية التحتية</h3>\r\n  <p>إنشاء وتدمير الموارد السحابية (<b>EC2, S3, Containers</b>) عبر الـ <b>APIs</b> للخدمات السحابية (AWS, Azure, GCP).</p>\r\n  <div class=\"mark m-fun\"><span class=\"tag\">ASIDE · تنويه من المجال</span>يُفضّل كثيرون استخدام <b>Terraform</b> للـ Provisioning (بناء الـ Infrastructure)، واستخدام <b>Ansible</b> للـ Configuration Management (إدارة ما داخل الـ Servers). فصل الاختصاص: الـ Contractor يبني، والفني يجهّز من الداخل. 🏗️🔧</div>\r\n  <h3 id=\"4-3network-automation-أتمتة-الشبكات\"><span class=\"n\">4.3</span>Network Automation — أتمتة الشبكات</h3>\r\n  <p>ضبط وإدارة الـ <b>Routers</b>، الـ <b>Switches</b>، والـ <b>Firewalls</b> برمجيًا عبر بروتوكولات الأتمتة — بدل الدخول لكل جهاز شبكة يدويًا عبر واجهته.</p>\r\n  <div class=\"taskhead\">TASK [خريطة القرار السريعة]<span class=\"hst\">which tool when?</span></div>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>مهمتك</th><th>الأداة الأنسب</th><th>لماذا</th></tr>\r\n    <tr><td>تثبيت Nginx على 20 Server</td><td><b>Ansible</b></td><td>Configuration داخل الأجهزة — مجالها الأول</td></tr>\r\n    <tr><td>إنشاء VPC و10 Instances على AWS</td><td><b>Terraform</b></td><td>Provisioning سحابي عبر API</td></tr>\r\n    <tr><td>مشروع كامل: بناء + تهيئة</td><td><b>الاثنان 🤝</b></td><td>Terraform يبني → Ansible يهيّئ</td></tr>\r\n    <tr><td>تحديث Firmware لـ Switches</td><td><b>Ansible</b></td><td>Network Automation — مجالها الثالث</td></tr>\r\n  </table></div></div>\r\n  <p>لاحظ: المقارنة ليست «الأفضل مقابل الأسوأ» بل «الأداة في مجالها» — Ansible يستطيع Provisioning، لكن Terraform أقوى فيه.</p>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>احفظ الثلاثية بالترتيب: <b>Configuration Management</b> (الأشهر) · <b>Infrastructure Provisioning</b> (سحابي، ونقاش Terraform) · <b>Network Automation</b> (Routers/Switches/Firewalls). سؤال «ما استخدامات Ansible؟» — هذه هي الإجابة النموذجية.</div>\r\n  <p>⏭️ المجالات واضحة — الآن نُجهّز العدة: التثبيت على كل الأنظمة → <a href=\"#ch-05\">الفصل 5: Installation</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 7 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-03\">السابق</a> · <a href=\"#ch-05\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 05</div><h1 id=\"installation-التثبيت-وإعداد-البيئة\">⚙️ Installation <span class=\"har\">— التثبيت وإعداد البيئة</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n  <p>يتم تثبيت Ansible <b>فقط على الـ Control Node</b> — قاعدة لا استثناء لها. اختر طريقك حسب نظامك:</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🍎 macOS — Homebrew</p><div class=\"code mini\"><span class=\"p\">$</span> brew install ansible</div></div>\r\n    <div class=\"panel\"><p>🐧 Ubuntu / Debian — apt</p><div class=\"code mini\"><span class=\"p\">$</span> sudo apt update &amp;&amp; sudo apt install ansible <span class=\"y\">-y</span></div></div>\r\n    <div class=\"panel\"><p>🐍 Any OS — Python Pip</p><div class=\"code mini\"><span class=\"p\">$</span> pip3 install ansible</div></div>\r\n    <div class=\"panel\"><p>🪟 Windows — WSL</p><p>استخدم بيئة <b>WSL</b> (Windows Subsystem for Linux) لتشغيل Ubuntu داخل Windows وتثبيت Ansible عليه بشكل طبيعي — ثم طبّق أمر Ubuntu أعلاه.</p></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [التحقق من التثبيت]<span class=\"hst\">verify installation</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible --version\r\nansible [core 2.16.3]\r\n  config file = /etc/ansible/ansible.cfg\r\n  python version = 3.10.12</div>\r\n  <p>رقم الـ Version ظهر = التثبيت نجح وأنت جاهز.</p>\r\n  <div class=\"taskhead\">TASK [إضافات VS Code المقترحة]<span class=\"hst\">editor setup</span></div>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">YAML Extension — Red Hat</span>\r\n    <span class=\"chipr\">Ansible Extension — Red Hat</span>\r\n  </div>\r\n  <p>Syntax Highlighting وValidation داخل المحرر — تكتشف أخطاء الـ Indentation قبل أن تصل للـ Run.</p>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>خطأ شائع: تثبيت Ansible على الـ Managed Nodes «احتياطًا». لا فائدة منه إطلاقًا — هي تستقبل الأوامر عبر SSH فقط. التثبيت للـ Control Node وحده.</div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG</span><code>pip3 install</code> هو الخيار المشترك لكل الأنظمة — مفيد خاصة إذا كان مدير الحزم في توزيعتك يقدّم Version قديمًا.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>ثلاث طرق تثبيت + Windows: <code>brew</code> (macOS) · <code>apt</code> (Ubuntu/Debian) · <code>pip3</code> (Any OS) · <b>WSL</b> (Windows). وسؤال «أين يُثبَّت Ansible؟» — <b>Control Node فقط</b>.</div>\r\n  <p>⏭️ الأداة جاهزة — لكن الاتصال بالـ Servers يحتاج تأمينًا: الـ SSH Keys → <a href=\"#ch-06\">الفصل 6</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 8 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-04\">السابق</a> · <a href=\"#ch-06\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 06 · PLAY</div><h1 id=\"ssh-keys-إعداد-الاتصال-الآمن-بدون-password\">🔐 SSH Keys <span class=\"har\">— إعداد الاتصال الآمن بدون Password</span></h1></div><span class=\"hmeta\">🟠 8 MIN</span></div></div>\r\n  <p>لكي تتمكن الـ Control Node من الاتصال بالـ Managed Nodes وتنفيذ الـ Instructions <b>تلقائيًا</b>، يُفضَّل إعداد الاتصال عبر مفاتيح الـ SSH — الـ <b>Public/Private Key Pair</b>.</p>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">Play — ثلاث Steps واكتمل الاتصال</div>\r\n    <div class=\"frow\">\r\n      <div class=\"blk\">1️⃣ ssh-keygen<small>أنشئ الـ Key Pair</small></div>\r\n      <span class=\"harrow\">──►</span>\r\n      <div class=\"blk\">2️⃣ ssh-copy-id<small>ارفع الـ Public Key</small></div>\r\n      <span class=\"harrow\">──►</span>\r\n      <div class=\"blk b-ok\">3️⃣ Test<small>بلا Password ✅</small></div>\r\n    </div>\r\n  </div>\r\n  <h3 id=\"6-1إنشاء-الـ-key-pair-على-الـ-control-node\"><span class=\"n\">6.1</span>إنشاء الـ Key Pair على الـ Control Node</h3>\r\n  <div class=\"code\"><span class=\"p\">$</span> ssh-keygen -t rsa -b 4096</div>\r\n  <p>سيتم إنشاء ملفين في المجلد <code>~/.ssh/</code>:</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🔑 id_rsa — Private Key</p><p>الـ <b>Private Key</b> — <b>يُحفظ بسريّة تامة</b> على الـ Control Node ولا يُشارك مع أي أحد أبدًا.</p></div>\r\n    <div class=\"panel\"><p>🗝️ id_rsa.pub — Public Key</p><p>الـ <b>Public Key</b> — هو الذي <b>يتم رفعه</b> إلى الـ Managed Nodes. قفله لا يفتح شيئًا.</p></div>\r\n  </div>\r\n  <h3 id=\"6-2نسخ-الـ-public-key-إلى-الـ-managed-node\"><span class=\"n\">6.2</span>نسخ الـ Public Key إلى الـ Managed Node</h3>\r\n  <div class=\"code\"><span class=\"p\">$</span> ssh-copy-id <span class=\"y\">-i</span> ~/.ssh/id_rsa.pub ubuntu@&lt;MANAGED_NODE_IP&gt;</div>\r\n  <h3 id=\"6-3اختبار-الاتصال-بدون-كلمة-سر\"><span class=\"n\">6.3</span>اختبار الاتصال بدون كلمة سر</h3>\r\n  <div class=\"code\"><span class=\"p\">$</span> ssh ubuntu@&lt;MANAGED_NODE_IP&gt;\r\n<span class=\"ok\">Welcome to Ubuntu 22.04 LTS …</span>   <span class=\"g\"># logged in — no password asked ✅</span>\r\n<span class=\"p\">$</span> exit</div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · AWS EC2</span>في حالة استخدام أجهزة AWS EC2، يتم استخدام ملف الـ Private Key بصيغة <code>.pem</code> المُقدَّم من AWS لتنسيق الاتصال الأول — والـ User غالبًا <code>ubuntu</code> أو <code>ec2-user</code> حسب الـ OS.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>خطآن شائعان: نسخ <code>id_rsa</code> (الـ Private) بدل <code>id_rsa.pub</code> (الـ Public) للسيرفر = لن يعمل الاتصال. ونسخ الـ Private عبر قنوات غير آمنة = ثغرة أمنية كاملة. الـ Public يسافر، الـ Private لا يتحرك أبدًا.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>التسلسل الحرفي: <code>ssh-keygen -t rsa -b 4096</code> ← <code>ssh-copy-id -i ~/.ssh/id_rsa.pub ubuntu@IP</code> ← اختبار <code>ssh ubuntu@IP</code>. ومن هذه اللحظة تصبح كل أوامر Ansible القادمة صامتة تمامًا — لا Password بينك وبين الأتمتة.</div>\r\n  <p>⏭️ القنوات مفتوحة — الآن نسلّم Ansible «عدته» وخريطته: <a href=\"#ch-07\">الفصل 7: Modules</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 9 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-05\">السابق</a> · <a href=\"#ch-07\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 07</div><h1 id=\"modules-وحدات-التنفيذ\">🧩 Modules <span class=\"har\">— وحدات التنفيذ</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n  <p>تعتمد جميع مهام Ansible على الـ <b>Modules</b> — وهي أدوات برمجية جاهزة تؤدي وظائف محددة. أنت لا تكتب Scripts، أنت تستدعي Modules وتعطيها الـ State المطلوبة.</p>\r\n  <div class=\"taskhead\">TASK [أشهر الـ Modules الأساسية]<span class=\"hst\">core modules</span></div>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>Module</th><th>وظيفته</th></tr>\r\n    <tr><td><code>apt</code> / <code>yum</code></td><td>لإدارة وتثبيت وتحديث وحذف الـ <b>Packages</b> (حسب الـ Distribution).</td></tr>\r\n    <tr><td><code>ping</code></td><td>لاختبار الاتصال والـ Readiness بين الـ Control Node والـ Managed Nodes.</td></tr>\r\n    <tr><td><code>service</code></td><td>لإدارة الـ <b>Services</b> — start, stop, restart.</td></tr>\r\n    <tr><td><code>copy</code></td><td>لنسخ الـ Files من الـ Control Node إلى الـ Managed Nodes.</td></tr>\r\n    <tr><td><code>command</code> / <code>shell</code></td><td>لتنفيذ أوامر النظام المباشرة على الـ Servers.</td></tr>\r\n  </table></div></div>\r\n  <p>الـ Modules بالمئات تغطي كل شيء تقريبًا — ويمكنك دائمًا الرجوع للوثائق الرسمية <b>(Ansible Documentation)</b> لمعرفة الـ Module المناسب وخياراته لكل Task.</p>\r\n  <div class=\"taskhead\">TASK [الـ Modules الثلاثة التي ستستخدمها أولًا]<span class=\"hst\">start here</span></div>\r\n  <div class=\"grid3\">\r\n    <div class=\"panel\"><p>ping</p><p>أول Module تجرّبه — يثبت أن الاتصال يعمل. الرد الناجح دائمًا: <code>\"pong\"</code>.</p></div>\r\n    <div class=\"panel\"><p>apt / yum</p><p>قلب إدارة الـ Packages. مع <code>state=present</code> يصبح الأمر Idempotent تلقائيًا.</p></div>\r\n    <div class=\"panel\"><p>service</p><p>يتحكم بحياة الـ Service: <code>started</code>, <code>stopped</code>, <code>restarted</code> — و<code>enabled</code> عند الـ Boot.</p></div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>الـ Module يخفي عنك الـ How: أنت تقول <code>apt: name=nginx state=present</code> — والـ Module يعرف بنفسه هل ينفّذ <code>apt-get install</code> فعليًا أم أن كل شيء موجود فيتجاهل. هذا هو جذر الـ Idempotency.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span><code>command</code> و<code>shell</code> قد يكونان فخًا: بهما تستطيع تجاوز كل أناقة Ansible وكتابة أوامر خام غير Idempotent. استخدمهما كملجأ أخير عندما لا يوجد Module مخصص لمهمتك.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>احفظ الخمسة الأساسيين بوظائفهم: <code>apt/yum</code> (Packages) · <code>ping</code> (Connectivity) · <code>service</code> (Services) · <code>copy</code> (Files) · <code>command/shell</code> (Direct commands). سؤال «ما الـ Module الذي تستخدمه لـ X؟» — من هذه القائمة تأتي الإجابات.</div>\r\n  <p>⏭️ العدة جاهزة — نحتاج الآن قائمة الأهداف: من سننفّذ عليهم؟ → <a href=\"#ch-08\">الفصل 8: Inventory</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 10 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-06\">السابق</a> · <a href=\"#ch-08\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 08</div><h1 id=\"inventory-ملف-الـ-managed-nodes\">🗂️ Inventory <span class=\"har\">— ملف الـ Managed Nodes</span></h1></div><span class=\"hmeta\">🟡 5 MIN</span></div></div>\r\n  <p>ملف الـ <b>Inventory</b> هو الملف الذي يحتوي على الـ <b>IPs</b> الخاصة بالـ Managed Nodes — مقسّمة إلى <span class=\"ten\">Groups</span> (مجموعات) تستهدفها في الأوامر.</p>\r\n  <div class=\"taskhead\">TASK [مثال لملف hosts.ini]<span class=\"hst\">inventory example</span></div>\r\n  <div class=\"code\"><span class=\"g\"># hosts.ini</span>\r\n<span class=\"c\">[web]</span>\r\n192.168.1.101 ansible_user=ubuntu\r\n192.168.1.102 ansible_user=ubuntu\r\n\r\n<span class=\"c\">[db]</span>\r\n192.168.1.201 ansible_user=ubuntu</div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · تشريح الملف</span><code>[web]</code> و<code>[db]</code> = أسماء الـ Groups بين أقواس مربعة · الأسطر تحتها = الـ IPs الأعضاء · <code>ansible_user=ubuntu</code> = الـ SSH User المستخدم للاتصال بذلك الـ Server — تُعرَّف مرة هنا بدل تكرارها في كل Command.</div>\r\n  <div class=\"taskhead\">TASK [كيف نستهدف؟]<span class=\"hst\">targeting</span></div>\r\n  <div class=\"frow\">\r\n    <span class=\"pill\">[web] → 2 Servers</span>\r\n    <span class=\"pill\">[db] → 1 Server</span>\r\n    <span class=\"pill\">all → 3 Servers</span>\r\n  </div>\r\n  <p><code>ansible web …</code> يضرب Servers الويب فقط · <code>ansible all …</code> يضرب الجميع · استهداف بالمجموعة بدل حفظ وحشو الـ IPs يدويًا كل مرة.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>الـ Inventory هو «مصدر الحقيقة» لخريطة بنيتك: أضف Server؟ سطر واحد في الـ File. غيّرت User؟ تعديل واحد. كل الـ Commands والـ Playbooks القادمة ستُحيل لهذا الملف عبر <code>-i hosts.ini</code>.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>أسماء الـ Groups حساسة تمامًا: <code>[web]</code> ليست <code>[webs]</code> ولا <code>[Web]</code>. خطأ حرف واحد في الاستهداف = «لا توجد Hosts مطابقة» — ورسالة الـ Error لن تنبّهك للـ Typo.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>الـ Inventory = ملف يحوي IPs الـ Managed Nodes مقسمة إلى Groups · الـ Syntax: <code>[group_name]</code> ثم الأسطر · <code>ansible_user</code> يعرّف الـ SSH User · يُمرَّر دائمًا بـ <code>-i</code>.</div>\r\n  <p>⏭️ لدينا الـ Modules والـ Inventory — وقت أول تنفيذ حقيقي، بلا أي File: → <a href=\"#ch-09\">الفصل 9: Ad-hoc Commands</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 11 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-07\">السابق</a> · <a href=\"#ch-09\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 09</div><h1 id=\"ad-hoc-commands-التنفيذ-الفوري\">⚡ Ad-hoc Commands <span class=\"har\">— التنفيذ الفوري</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <p>تُستخدم الـ Ad-hoc Commands لتنفيذ <b>مهمة سريعة بدون الحاجة لكتابة Playbook كامل</b> — سطر واحد مباشرة من الـ Terminal. هذا هو الجانب Imperative الذي ذكرناه في الفصل الأول.</p>\r\n  <div class=\"taskhead\">TASK [الصيغة العامة]<span class=\"hst\">general syntax</span></div>\r\n  <div class=\"code\">ansible &lt;group_or_all&gt; <span class=\"y\">-i</span> &lt;inventory_file&gt; <span class=\"y\">-m</span> &lt;module_name&gt; <span class=\"y\">-a</span> <span class=\"s\">\"&lt;module_arguments&gt;\"</span></div>\r\n  <div class=\"taskhead\">TASK [الأمثلة العملية الثلاثة]<span class=\"hst\">practical examples</span></div>\r\n  <p><b>1️⃣ فحص الاتصال — ping لكل الـ Servers:</b></p>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible all <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-m</span> ping\r\n192.168.1.101 | <span class=\"ok\">SUCCESS</span> =&gt; { <span class=\"s\">\"ping\"</span>: <span class=\"s\">\"pong\"</span> }\r\n192.168.1.102 | <span class=\"ok\">SUCCESS</span> =&gt; { <span class=\"s\">\"ping\"</span>: <span class=\"s\">\"pong\"</span> }\r\n192.168.1.201 | <span class=\"ok\">SUCCESS</span> =&gt; { <span class=\"s\">\"ping\"</span>: <span class=\"s\">\"pong\"</span> }</div>\r\n  <p><b>2️⃣ معرفة الـ Uptime لـ Servers الويب — المجموعة web:</b></p>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible web <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-a</span> <span class=\"s\">\"uptime\"</span></div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG</span>ملاحظة ذكية: عند عدم تحديد <code>-m</code> يتم استخدام الـ <code>command</code> Module <b>افتراضيًا</b> — لهذا كتبنا <code>uptime</code> مباشرة في <code>-a</code> دون تحديد Module.</div>\r\n  <p><b>3️⃣ التأكد من تثبيت Nginx على جميع الـ Servers:</b></p>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible all <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-m</span> apt <span class=\"y\">-a</span> <span class=\"s\">\"name=nginx state=present\"</span> <span class=\"y\">--become</span></div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span><code>--become</code> = صلاحيات root (مثل sudo) — الـ Installation يحتاجها دائمًا. و<code>state=present</code> هي لغة الـ Idempotency: «تأكد أنه موجود» — موجود أصلًا؟ لا شيء يحدث إطلاقًا.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>متى Ad-hoc ومتى Playbook؟ Ad-hoc لمهمة <b>سريعة ولن تتكرر</b> — فحص، Restart، استعلام. أول ما تشعر أن الـ Command سيُعاد لاحقًا أو يُشارك مع الفريق → انقله فورًا إلى Playbook (الفصل القادم).</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>احفظ الهيكل بالترتيب: <b>Target ← Inventory (-i) ← Module (-m) ← Arguments (-a) ← Become</b>. وسؤال الفهم الكلاسيكي: «لماذا لم نكتب <code>-m command</code> في مثال uptime؟» — لأنه الـ Module الافتراضي.</div>\r\n  <p>⏭️ الأوامر المنفردة تنجز Task واحدة — السيناريوهات الكاملة تحتاج File منظمًا. ولغته أولًا: → <a href=\"#ch-10\">الفصل 10: YAML</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 12 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-08\">السابق</a> · <a href=\"#ch-10\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 10</div><h1 id=\"yaml-basics-أساسيات-الصيغة\">📜 YAML Basics <span class=\"har\">— أساسيات الصيغة</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <p>تعتمد لغة YAML على الـ <b>Indentation</b> (المسافات البادئة) — ليست لغة برمجة بل طريقة مرتبة لوصف الـ Data. إتقان قواعدها = كتابة Playbooks بلا صداع.</p>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT · القاعدة الأهم</span>لا تستخدم <b>Tab</b> أبدًا — استخدم <b>مسافتين (Spaces)</b> دائمًا. خلط Tab مع Spaces هو أكثر سبب لفشل ملفات YAML عند المبتدئين، والـ Error يظهر بعيدًا عن سطره الحقيقي فيصعب تتبعه.</div>\r\n  <div class=\"taskhead\">TASK [القاعدة الأولى]<span class=\"hst\">document start</span></div>\r\n  <p>تبدأ الملفات دائمًا بثلاث شرطات <code>---</code> — إعلان بداية الـ YAML Document:</p>\r\n  <div class=\"code\">---</div>\r\n  <div class=\"taskhead\">TASK [هياكل البيانات الثلاثة]<span class=\"hst\">data structures</span></div>\r\n  <div class=\"grid3\">\r\n    <div class=\"panel\"><p>① Key-Value</p><div class=\"code mini\"><span class=\"c\">name:</span> Ahmed</div><p>مفتاح وقيمة — أبسط بنية.</p></div>\r\n    <div class=\"panel\"><p>② Dictionary</p><div class=\"code mini\"><span class=\"c\">employee:</span>\r\n  <span class=\"c\">name:</span> Mohamed\r\n  <span class=\"c\">age:</span> 30\r\n  <span class=\"c\">is_manager:</span> <span class=\"s\">true</span></div><p>قاموس — مفاتيح متعددة تحت مفتاح أب.</p></div>\r\n    <div class=\"panel\"><p>③ List</p><div class=\"code mini\"><span class=\"c\">skills:</span>\r\n  <span class=\"y\">-</span> Linux\r\n  <span class=\"y\">-</span> Ansible\r\n  <span class=\"y\">-</span> Docker</div><p>قائمة — شرطة لكل عنصر.</p></div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>الـ Playbook الذي سنكتبه في الفصل القادم ليس شيئًا جديدًا — هو <b>قائمة من القواميس (List of Dictionaries)</b> بالضبط: الـ Play عنصر في List، وكل Task داخله Dictionary. مَن فهم هذه الهياكل الثلاثة، فهم Ansible كله.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>في الـ Dictionary: لاحظ أن <code>name</code> و<code>age</code> بادئة بمسافتين تحت <code>employee</code> — هذا الـ Indentation هو ما يجعلهما <b>داخله</b>. لو صنفتهما بمستواه لصارا Key-Value مستقلين منفصلين تمامًا.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>قواعد YAML الثلاثة الذهبية: <b>① ابدأ بـ <code>---</code> · ② Spaces لا Tabs · ③ ثلاث هياكل فقط: Key-Value, Dictionaries, Lists</b>. كل تعقيد لاحق في الـ Playbooks هو تركيب لهذه الثلاثة.</div>\r\n  <p>⏭️ اللغة بين يديك — الوقت جاء: أول Playbook حقيقي كامل → <a href=\"#ch-11\">الفصل 11</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 13 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-09\">السابق</a> · <a href=\"#ch-11\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 11 · PLAY</div><h1 id=\"playbooks-كتابة-وتشغيل\">📖 Playbooks <span class=\"har\">— كتابة وتشغيل</span></h1></div><span class=\"hmeta\">🟠 9 MIN</span></div></div>\r\n  <p>الـ <b>Playbook</b> هو ملف YAML يحتوي على مجموعة من الـ <b>Plays</b>، وكل Play تحتوي مجموعة من الـ <b>Tasks</b> — لتنفيذ سيناريو Automation كامل على مجموعة Servers محددة. هذا هو قلب Ansible النابض.</p>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">Hierarchy — التسلسل الهرمي</div>\r\n    <div class=\"frow\">\r\n      <div class=\"blk b-red\">Playbook<small>site.yml</small></div>\r\n      <span class=\"harrow\">◂ يحتوي</span>\r\n      <div class=\"blk\">Plays<small>hosts · become</small></div>\r\n      <span class=\"harrow\">◂ تحتوي</span>\r\n      <div class=\"blk\">Tasks<small>steps</small></div>\r\n      <span class=\"harrow\">◂ تستدعي</span>\r\n      <div class=\"blk\">Modules<small>apt · service</small></div>\r\n    </div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [مثال: Playbook لتثبيت وتشغيل Apache]<span class=\"hst\">أنشئ ملف site.yml</span></div>\r\n  <div class=\"code\"><span class=\"g\">---</span>\r\n<span class=\"y\">- name:</span> Install and Start Apache Web Server\r\n  <span class=\"c\">hosts:</span> web\r\n  <span class=\"c\">become:</span> yes\r\n\r\n  <span class=\"c\">tasks:</span>\r\n    <span class=\"y\">- name:</span> Install Apache Package\r\n      <span class=\"c\">apt:</span>\r\n        <span class=\"c\">name:</span> apache2\r\n        <span class=\"c\">state:</span> present\r\n\r\n    <span class=\"y\">- name:</span> Ensure Apache Service is Running and Enabled\r\n      <span class=\"c\">service:</span>\r\n        <span class=\"c\">name:</span> apache2\r\n        <span class=\"c\">state:</span> started\r\n        <span class=\"c\">enabled:</span> yes</div>\r\n  <div class=\"taskhead\">TASK [تشغيل الـ Playbook]<span class=\"hst\">execute it</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> ansible-playbook <span class=\"y\">-i</span> hosts.ini site.yml\r\n<span class=\"g\">PLAY [Install and Start Apache Web Server]</span>\r\nTASK [Gathering Facts] <span class=\"ok\">ok: [192.168.1.101]</span>\r\nTASK [Install Apache Package] <span class=\"chg\">changed: [192.168.1.101]</span>\r\nTASK [Ensure Apache Service is Running and Enabled] <span class=\"chg\">changed: [192.168.1.101]</span>\r\n<span class=\"g\">PLAY RECAP</span>\r\n192.168.1.101 : <span class=\"ok\">ok=3</span> <span class=\"chg\">changed=2</span> failed=0</div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · قراءة سطرًا بسطر</span><code>hosts: web</code> → استهدف Group الـ web من الـ Inventory · <code>become: yes</code> → نفّذ بصلاحيات root · كل Task = <b>Name</b> وصفي + <b>Module</b> + <b>State</b> مطلوبة. لاحظ الصياغة: لا نقول «ثبّت» بل «اجعله present».</div>\r\n  <div class=\"mark m-ok\"><span class=\"tag\">PROOF</span><b>شغّله مرة ثانية الآن.</b> النتيجة: <code>changed=0</code> وكل الـ Tasks <span class=\"stbad st-ok\">ok</span> — الـ Idempotency حيّة أمام عينيك: الـ State متحققة فلا تغيير. ♻️</div>\r\n  <p>⏭️ ثبّتنا وشغّلنا — الإزالة النظيفة وقراءة النتائج باحتراف: → <a href=\"#ch-11b\">الفصل 11·b</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 14 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-10\">السابق</a> · <a href=\"#ch-11b\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 11·b</div><h1 id=\"playbooks-الإزالة-وقراءة-النتائج\">🧹 Playbooks <span class=\"har\">— الإزالة وقراءة النتائج</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <p>نفس القوة التي تُثبّت تُزيل — بعكس الـ State فقط. ثم نتقن قراءة مؤشرات النتائج الثلاثة.</p>\r\n  <div class=\"taskhead\">TASK [Playbook لإيقاف وحذف Apache]<span class=\"hst\">remove playbook</span></div>\r\n  <div class=\"code\"><span class=\"g\">---</span>\r\n<span class=\"y\">- name:</span> Stop and Remove Apache Web Server\r\n  <span class=\"c\">hosts:</span> web\r\n  <span class=\"c\">become:</span> yes\r\n\r\n  <span class=\"c\">tasks:</span>\r\n    <span class=\"y\">- name:</span> Stop Apache Service\r\n      <span class=\"c\">service:</span>\r\n        <span class=\"c\">name:</span> apache2\r\n        <span class=\"c\">state:</span> stopped\r\n\r\n    <span class=\"y\">- name:</span> Remove Apache Package\r\n      <span class=\"c\">apt:</span>\r\n        <span class=\"c\">name:</span> apache2\r\n        <span class=\"c\">state:</span> absent</div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>الترتيب العكسي المنطقي: <b>نوقف الـ Service أولًا</b> ثم نحذف الـ Package — حذف حزمة والـ Service الخاصة بها تعمل = سلوك غير متوقع. وكلمة السر كلها في الـ <code>state</code>: <code>present / absent / started / stopped</code> — أربع Values تحكم العالم.</div>\r\n  <div class=\"taskhead\">TASK [مؤشرات النتائج]<span class=\"hst\">result indicators</span></div>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>المؤشر</th><th>اللون</th><th>المعنى</th></tr>\r\n    <tr><td><span class=\"stbad st-ok\">ok</span></td><td>أخضر</td><td>الـ Server في الـ Desired State <b>بالفعل</b> — لم يتطلب تغييرًا.</td></tr>\r\n    <tr><td><span class=\"stbad st-chg\">changed</span></td><td>أصفر</td><td>تم إجراء الـ Change بنجاح على الـ Server.</td></tr>\r\n    <tr><td><span class=\"stbad st-fail\">failed</span></td><td>أحمر</td><td>حدث Error في الـ Task — توقف التنفيذ على ذلك الـ Server.</td></tr>\r\n  </table></div></div>\r\n  <div class=\"mark m-fail\"><span class=\"tag\">RESCUED · لو ظهر failed</span>اقرأ اسم الـ Task الأحمر أولًا — يخبرك <b>أي Step</b> فشلت، ثم السطر أسفلها — يخبرك <b>لماذا</b> (شبكة؟ Permissions؟ اسم Package خاطئ؟). 90% من الأعطال تُحل من هذه السطور دون أي بحث خارجي.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>الفرق الجوهري بين ok وchanged هو <b>جوهر فلسفة Ansible</b>: ok = الـ State متحققة مسبقًا (الـ Idempotency تعمل)، changed = عمل حقيقي تم الآن. وقراءة failed تبدأ من اسم الـ Task + الـ Error Message تحته.</div>\r\n  <p>⏭️ File واحد أنجز سيناريو كاملًا — لكن مع كبر الـ Projects يصير وحشًا. التنظيم النهائي: → <a href=\"#ch-12\">الفصل 12: Roles &amp; Galaxy</a></p>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 15 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-11\">السابق</a> · <a href=\"#ch-12\">التالي</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Chapter 12</div><h1 id=\"roles-amp-galaxy-التنظيم-والمشاركة\">🎭 Roles &amp; Galaxy <span class=\"har\">— التنظيم والمشاركة</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n  <p>عندما تكبر مشاريع الـ Automation، يصبح وضع جميع المهام والتعليمات في ملف Playbook واحد <b>صعب الصيانة</b>. تعطينا <b>Ansible Roles</b> هيكلية مجلدات قياسية لتنظيم الـ Project وتجزئته إلى مكونات <b>Modular &amp; Reusable</b>.</p>\r\n  <div class=\"taskhead\">TASK [الهيكل التنظيمي للـ Role]<span class=\"hst\">role structure</span></div>\r\n  <div class=\"tree\"><b>my_role/</b>\r\n├── <u>tasks/</u>       <span class=\"g\"># main.yml — الـ Tasks الرئيسية</span>\r\n├── <i>handlers/</i>    <span class=\"g\"># الـ Tasks المشروطة (Handlers)</span>\r\n├── <em>templates/</em>   <span class=\"g\"># قوالب Jinja2</span>\r\n├── <em>files/</em>       <span class=\"g\"># الملفات الثابتة المراد نقلها</span>\r\n├── <i>vars/</i>        <span class=\"g\"># الـ Variables الخاصة بالـ Role</span>\r\n├── <i>defaults/</i>    <span class=\"g\"># الـ Variables الافتراضية</span>\r\n└── <i>meta/</i>        <span class=\"g\"># معلومات عن الـ Role والاعتمادات</span></div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>الـ Role = <b>Encapsulation</b> — تغليف. بدل Playbook من 200 سطر، تستدعي Role باسمه، وكل من يقرأ الـ Project يفهم الـ Structure فورًا لأن الجميع يعرف هذا الهيكل القياسي.</div>\r\n  <div class=\"taskhead\">TASK [منصة Ansible Galaxy]<span class=\"hst\">galaxy</span></div>\r\n  <p>مستودع رسمي مفتوح المصدر يُمكّنك من <b>مشاركة وتنزيل</b> الـ <b>Roles</b> والـ <b>Collections</b> الجاهزة المبنية من قبل مجتمع Ansible — لتسريع عمليات الـ Development والأتمتة. بدل بناء Role لـ Apache من الصفر: ابحث في Galaxy، نزّل، وعدّل لاحتياجك.</p>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">galaxy.ansible.com</span>\r\n    <span class=\"chipr\">Ready-made Roles</span>\r\n    <span class=\"chipr\">Collections</span>\r\n    <span class=\"chipr\">Community-driven</span>\r\n  </div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>متى تكتب Role بدل Playbook؟ قاعدة عملية: أول Playbook لك = Playbook عادي. عندما يبدأ الملف بالتكرار أو تجد نفس الـ Tasks في Projects متعددة = وقت التجزئة إلى Roles. لا تبدأ بالتعقيد.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>اجمع رسالة الكتاب كلها في جملة — سؤال الـ Interview الختامي: «ما Ansible؟» → أداة <b>Agentless Automation</b> عبر SSH، بـ <b>YAML Declarative Syntax</b> للـ Desired State، تتسم بالـ <b>Idempotency</b>، تنظم عملها بـ Inventory وPlaybooks وتتوسع بـ Roles وGalaxy.</div>\r\n  <div class=\"panel\"><p>🏁 ختامًا</p><p>هذا الدليل يلخص جميع الأساسيات والمفاهيم العملية التي تم شرحها في الدورة التعليمية لقناة <b>Cloud Code</b> — ويمكن الاعتماد عليه كمرجع سريع ومكتوب أثناء كتابة وتنفيذ سيناريوهات الأتمتة. ثم طبّق: Virtual Machine كـ Control Node + Server مُدار، وأعد بناء كل الأمثلة بيدك — الـ Automation تُتقن بالممارسة. ▶</p></div>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 16 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-11b\">السابق</a> · <a href=\"#quiz\">الاختبار ▶</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Self Check</div><h1 id=\"اختبر-نفسك-12-سؤالًا\">🎯 اختبر نفسك — 12 سؤالًا</h1></div><span class=\"hmeta\">⏱ 10 MIN</span></div></div>\r\n  <p>غطِّ الإجابات حتى تحل الاثني عشر كلها. 10+ صحيح = جاهز عمليًا.</p>\r\n  <div class=\"tocgrid\">\r\n    <div>\r\n      <div class=\"qz\"><span class=\"qn\">1.</span>ما المجالان الأساسيان اللذان تُستخدم فيهما Ansible؟</div>\r\n      <div class=\"qz\"><span class=\"qn\">2.</span>ما المتطلب الوحيد على Managed Nodes الـ Linux؟</div>\r\n      <div class=\"qz\"><span class=\"qn\">3.</span>على أي Node يُثبَّت Ansible؟</div>\r\n      <div class=\"qz\"><span class=\"qn\">4.</span>عرّف Idempotency بجملة واحدة مع مثال.</div>\r\n      <div class=\"qz\"><span class=\"qn\">5.</span>ما الفرق بين Declarative وImperative في Ansible؟</div>\r\n      <div class=\"qz\"><span class=\"qn\">6.</span>اكتب Command إنشاء SSH Key Pair بطول 4096.</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"qz\"><span class=\"qn\">7.</span>أي Key يُرفع إلى الـ Managed Node — وماذا يحدث لو رفعت الآخر؟</div>\r\n      <div class=\"qz\"><span class=\"qn\">8.</span>اذكر وظائف الـ Modules الخمسة الأساسية: apt/yum, ping, service, copy, command/shell.</div>\r\n      <div class=\"qz\"><span class=\"qn\">9.</span>ماذا تعبر عنه المجموعات في الـ Inventory مثل [web]؟</div>\r\n      <div class=\"qz\"><span class=\"qn\">10.</span>ما الـ Module الافتراضي في Ad-hoc عند حذف -m؟</div>\r\n      <div class=\"qz\"><span class=\"qn\">11.</span>ماذا تعني changed=0 في PLAY RECAP بعد التشغيل الثاني؟</div>\r\n      <div class=\"qz\"><span class=\"qn\">🔥</span><b>سؤال الشرف:</b> مميزات Ansible الأربع + مجالاته الثلاثة + جملة التعريف الكاملة — من الذاكرة.</div>\r\n    </div>\r\n  </div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG</span>الأسئلة تغطي الفصول الـ 12 بالتسلسل. أي تعثر → عد لفصلها من <a href=\"#toc\">الفهرس</a> قبل فتح الإجابات.</div>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 17 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#ch-12\">السابق</a> · <a href=\"#answers\">الإجابات ▶</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Answer Key</div><h1 id=\"مفتاح-الإجابات-التقييم\">✅ مفتاح الإجابات + التقييم</h1></div><span class=\"hmeta\">لا غش 😄</span></div></div>\r\n  <div class=\"table-scroll\"><table>\r\n    <tr><th>#</th><th>الإجابة</th><th>السبب</th></tr>\r\n    <tr><td>1</td><td><b>Configuration Management</b> + <b>Infrastructure Provisioning</b></td><td>المجالان الأساسيان — الثالث: Network Automation</td></tr>\r\n    <tr><td>2</td><td><b>Python</b> فقط</td><td>مثبتة افتراضيًا في أغلب التوزيعات — لا Agents</td></tr>\r\n    <tr><td>3</td><td><b>الـ Control Node فقط</b></td><td>الـ Managed Nodes تستقبل عبر SSH دون تثبيت</td></tr>\r\n    <tr><td>4</td><td>تنفيذ نفس الـ Script مرارًا <b>لا يغيّر شيئًا إلا عند الحاجة الفعلية</b> — مثال: Apache مثبت مسبقًا → لا تغيير</td><td>الـ Desired State متحقق → ok</td></tr>\r\n    <tr><td>5</td><td><b>Declarative</b> في الـ Playbooks (تحدد الـ State) · <b>Imperative</b> في الـ Ad-hoc Commands (أمر فوري)</td><td>أسلوبان لموقفين مختلفين</td></tr>\r\n    <tr><td>6</td><td><code>ssh-keygen -t rsa -b 4096</code></td><td>-t النوع (rsa) · -b الطول (4096 bit)</td></tr>\r\n    <tr><td>7</td><td><b>id_rsa.pub — الـ Public Key</b> · رفعت الـ Private؟ لن يعمل الاتصال + ثغرة أمنية</td><td>الـ Public يُرفع، الـ Private يبقى سريًا</td></tr>\r\n    <tr><td>8</td><td>apt/yum = Packages · ping = Connectivity · service = Services (start/stop/restart) · copy = Files · command/shell = Direct commands</td><td>الخمسة الأساسية — كل شيء آخر يُبنى عليها</td></tr>\r\n    <tr><td>9</td><td>الـ IPs الخاصة بالـ Managed Nodes — الـ Groups = <b>وحدات Targeting</b> بنفس اسم المجموعة</td><td>نستهدف [web] أو all بدل الـ IPs</td></tr>\r\n    <tr><td>10</td><td><b>command</b></td><td>الافتراضي عند غياب -m</td></tr>\r\n    <tr><td>11</td><td>الـ State كانت متحققة أصلًا — <b>الـ Idempotency عملت</b> ♻️</td><td>نفس الـ Playbook مرتان = صفر Changes</td></tr>\r\n  </table></div>\r\n  <div class=\"mark m-ok\"><span class=\"tag\">PROOF · 🔥 سؤال الشرف</span>المميزات الأربع: <b>Agentless · Simple YAML Syntax · Declarative Approach · Idempotency</b> — والمجالات الثلاثة: <b>Configuration Management · Infrastructure Provisioning · Network Automation</b>. والجملة الكاملة: أداة Agentless Automation عبر SSH، بـ YAML Declarative للـ Desired State، Idempotent، منظمة بـ Inventory وPlaybooks، متوسعة بـ Roles وGalaxy. أجبتها من الذاكرة؟ أنت تفهم Ansible لا تحفظه.</div>\r\n  <div class=\"taskhead\">TASK [احسب نتيجتك]<span class=\"hst\">scoring</span></div>\r\n  <div class=\"grid3\">\r\n    <div class=\"panel\"><p>10–12 · 🏆 جاهز عمليًا</p><p>انتقل لبناء Roles حقيقية ومشروع Automation متكامل.</p></div>\r\n    <div class=\"panel\"><p>7–9 · 💪 متين</p><p>أعد الفصول التي أخطأت فيها ثم أعد الاختبار.</p></div>\r\n    <div class=\"panel\"><p>&lt;7 · 🔁 إعادة</p><p>نفّذ أمثلة الكتاب يدويًا على lab حقيقي — الفعل يثبّت أكثر من القراءة.</p></div>\r\n  </div>\r\n  <div class=\"folio\"><span>📘 Ansible — الدليل الشامل · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 18 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#quiz\">الأسئلة</a> · <a href=\"#cheatsheet\">المرجع ▶</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Cheat Sheet</div><h1 id=\"الورقة-المرجعية-اطبعها-وعلّقها\">📌 الورقة المرجعية — اطبعها وعلّقها</h1></div><span class=\"hmeta\">PRINT 🖨️</span></div></div>\r\n  <div class=\"tree\">▶ <b>FULL FLOW:</b>      keygen → ssh-copy-id → inventory → ad-hoc/playbook → recap\r\n▶ <b>ARCHITECTURE:</b>  Control Node ──SSH──► Managed Nodes (Agentless · Python only)\r\n▶ <b>STRUCTURE:</b>      Playbook → Plays → Tasks → Modules   ·   scale up: Roles → Galaxy</div>\r\n  <div class=\"grid2\">\r\n    <div>\r\n      <div class=\"zlabel\">⚙️ Setup Commands</div>\r\n      <div class=\"code mini\"><span class=\"p\">$</span> brew install ansible\r\n<span class=\"p\">$</span> sudo apt update &amp;&amp; sudo apt install ansible <span class=\"y\">-y</span>\r\n<span class=\"p\">$</span> pip3 install ansible\r\n<span class=\"p\">$</span> ansible --version\r\n<span class=\"p\">$</span> ssh-keygen <span class=\"y\">-t</span> rsa <span class=\"y\">-b</span> 4096\r\n<span class=\"p\">$</span> ssh-copy-id <span class=\"y\">-i</span> ~/.ssh/id_rsa.pub user@ip\r\n<span class=\"p\">$</span> ssh user@ip</div>\r\n      <div class=\"zlabel\">⚡ Ad-hoc Syntax</div>\r\n      <div class=\"code mini\">ansible &lt;group&gt; <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-m</span> &lt;module&gt; <span class=\"y\">-a</span> <span class=\"s\">\"args\"</span>\r\nansible all <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-m</span> ping\r\nansible web <span class=\"y\">-i</span> hosts.ini <span class=\"y\">-a</span> <span class=\"s\">\"uptime\"</span>\r\nansible all <span class=\"y\">-m</span> apt <span class=\"y\">-a</span> <span class=\"s\">\"name=nginx state=present\"</span> <span class=\"y\">--become</span></div>\r\n    </div>\r\n    <div>\r\n      <div class=\"zlabel\">📖 Playbook Structure</div>\r\n      <div class=\"code mini\"><span class=\"g\">---</span>\r\n<span class=\"y\">- name:</span> scenario name\r\n  <span class=\"c\">hosts:</span> web\r\n  <span class=\"c\">become:</span> yes\r\n  <span class=\"c\">tasks:</span>\r\n    <span class=\"y\">- name:</span> task name\r\n      <span class=\"c\">apt:</span>\r\n        <span class=\"c\">name:</span> apache2\r\n        <span class=\"c\">state:</span> present\r\n\r\n<span class=\"g\"># run:</span>\r\nansible-playbook <span class=\"y\">-i</span> hosts.ini site.yml</div>\r\n      <div class=\"zlabel\">🚨 State Values</div>\r\n      <div class=\"table-scroll\"><table>\r\n        <tr><td>present / absent</td><td>Package: موجود / محذوف</td></tr>\r\n        <tr><td>started / stopped</td><td>Service: تعمل / متوقفة</td></tr>\r\n        <tr><td>enabled: yes</td><td>تشتغل عند الـ Boot</td></tr>\r\n        <tr><td><span class=\"stbad st-ok\">ok</span> متحقق · <span class=\"stbad st-chg\">changed</span> تغيّر · <span class=\"stbad st-fail\">failed</span> خطأ</td></tr>\r\n      </table></div>\r\n    </div>\r\n  </div>\r\n  <div class=\"tree\"><b>my_role/</b>   tasks/ · handlers/ · templates/ · files/ · vars/ · defaults/ · meta/   <span class=\"g\"># + galaxy.ansible.com</span></div>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">Agentless</span><span class=\"chipr\">Simple YAML</span><span class=\"chipr\">Declarative</span><span class=\"chipr\">Idempotent</span><span class=\"chipr\">Inventory Groups</span><span class=\"chipr\">Roles + Galaxy</span>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · الجملة الختامية</span><b>أنت تكتب الـ Desired State مرة واحدة — وAnsible يحققها على كل الـ Managed Nodes، ولا يلمس شيئًا إن لم يكن التغيير ضروريًا.</b> هذه هي الـ Automation كما يجب أن تكون. ▶</div>\r\n  <div class=\"folio\"><span>📘 Ansible · <span class=\"by\">By Nabawy</span> · بُني على شرح قناة Cloud Code</span><span class=\"fnum\">— 19 —</span><span><a href=\"#toc\">▤ TOC</a></span><span>▶ The End 🎬</span></div>\r\n</div>\r\n\r\n\r\n","toc":[{"id":"الدليل-الشامللتعلُّم-ansible","text":"الدليل الشامللتعلُّم Ansible","level":1},{"id":"المحتويات","text":"📖 المحتويات","level":1},{"id":"الملخص-التنفيذي-الطريق-كاملًا","text":"🗺️ الملخص التنفيذي — الطريق كاملًا","level":1},{"id":"intro-مقدمة-ونظرة-عامة","text":"🤖 Intro — مقدمة ونظرة عامة","level":1},{"id":"1-1agentless-بدون-عميل","text":"1.1Agentless — بدون عميل","level":3},{"id":"1-2simple-syntax-صيغة-بسيطة","text":"1.2Simple Syntax — صيغة بسيطة","level":3},{"id":"1-3declarative-approach-الأسلوب-التوصيفي","text":"1.3Declarative Approach — الأسلوب التوصيفي","level":3},{"id":"1-4idempotency-التكرار-الآمن","text":"1.4Idempotency — التكرار الآمن ♻️","level":3},{"id":"architecture-معمارية-ansible","text":"🏗️ Architecture — معمارية Ansible","level":1},{"id":"2-1control-node-عقدة-التحكم","text":"2.1Control Node — عقدة التحكم","level":3},{"id":"2-2managed-nodes-targets-العقد-المُدارة","text":"2.2Managed Nodes (Targets) — العقد المُدارة","level":3},{"id":"comparison-مقارنة-طرق-إدارة-الـ-servers","text":"⚖️ Comparison — مقارنة طرق إدارة الـ Servers","level":1},{"id":"use-cases-مجالات-الاستخدام-الرئيسية","text":"🌍 Use Cases — مجالات الاستخدام الرئيسية","level":1},{"id":"4-1configuration-management-إدارة-الإعدادات","text":"4.1Configuration Management — إدارة الإعدادات","level":3},{"id":"4-2infrastructure-provisioning-بناء-البنية-التحتية","text":"4.2Infrastructure Provisioning — بناء البنية التحتية","level":3},{"id":"4-3network-automation-أتمتة-الشبكات","text":"4.3Network Automation — أتمتة الشبكات","level":3},{"id":"installation-التثبيت-وإعداد-البيئة","text":"⚙️ Installation — التثبيت وإعداد البيئة","level":1},{"id":"ssh-keys-إعداد-الاتصال-الآمن-بدون-password","text":"🔐 SSH Keys — إعداد الاتصال الآمن بدون Password","level":1},{"id":"6-1إنشاء-الـ-key-pair-على-الـ-control-node","text":"6.1إنشاء الـ Key Pair على الـ Control Node","level":3},{"id":"6-2نسخ-الـ-public-key-إلى-الـ-managed-node","text":"6.2نسخ الـ Public Key إلى الـ Managed Node","level":3},{"id":"6-3اختبار-الاتصال-بدون-كلمة-سر","text":"6.3اختبار الاتصال بدون كلمة سر","level":3},{"id":"modules-وحدات-التنفيذ","text":"🧩 Modules — وحدات التنفيذ","level":1},{"id":"inventory-ملف-الـ-managed-nodes","text":"🗂️ Inventory — ملف الـ Managed Nodes","level":1},{"id":"ad-hoc-commands-التنفيذ-الفوري","text":"⚡ Ad-hoc Commands — التنفيذ الفوري","level":1},{"id":"yaml-basics-أساسيات-الصيغة","text":"📜 YAML Basics — أساسيات الصيغة","level":1},{"id":"playbooks-كتابة-وتشغيل","text":"📖 Playbooks — كتابة وتشغيل","level":1},{"id":"playbooks-الإزالة-وقراءة-النتائج","text":"🧹 Playbooks — الإزالة وقراءة النتائج","level":1},{"id":"roles-amp-galaxy-التنظيم-والمشاركة","text":"🎭 Roles &amp; Galaxy — التنظيم والمشاركة","level":1},{"id":"اختبر-نفسك-12-سؤالًا","text":"🎯 اختبر نفسك — 12 سؤالًا","level":1},{"id":"مفتاح-الإجابات-التقييم","text":"✅ مفتاح الإجابات + التقييم","level":1},{"id":"الورقة-المرجعية-اطبعها-وعلّقها","text":"📌 الورقة المرجعية — اطبعها وعلّقها","level":1}],"words":5110,"assets":[]};